-- 0006_add_org_partner — generated by `pnpm gen:migration`. Additive and reversible (ocs-db-migration);
-- never edit a migration once it is on main (CI pr-rules).
-- Partners are anonymous to clients (CLAUDE.md §3 rule 5, E1 AC4): the real name lives in `partner`, which
-- only staff can read; a client sees the per-client label (Partner A/B/C) in `partner_assignment`.
CREATE TABLE partner (
  id           uuid PRIMARY KEY,
  real_name    text NOT NULL,
  country_code text NOT NULL CHECK (country_code ~ '^[A-Z]{2}$'),
  created_at   timestamptz NOT NULL DEFAULT now(),
  archived_at  timestamptz
);

ALTER TABLE partner ENABLE ROW LEVEL SECURITY;
CREATE POLICY partner_internal ON partner FOR ALL TO ocs_app
  USING (app.is_internal()) WITH CHECK (app.is_internal());
-- No client and no partner policy: nobody outside staff ever reads a real name from here.
GRANT SELECT, INSERT, UPDATE ON partner TO ocs_app;

-- The partner working for a client, under the label that client sees. Letters are given in order of
-- assignment and never reused within the client (archived assignments keep theirs).
CREATE TABLE partner_assignment (
  id          uuid PRIMARY KEY,
  client_id   uuid NOT NULL REFERENCES client (id),
  partner_id  uuid NOT NULL REFERENCES partner (id),
  letter      text NOT NULL CHECK (letter ~ '^[A-Z]$'),
  created_at  timestamptz NOT NULL DEFAULT now(),
  archived_at timestamptz,
  UNIQUE (client_id, partner_id),
  UNIQUE (client_id, letter)
);
CREATE INDEX partner_assignment_client ON partner_assignment (client_id);

ALTER TABLE partner_assignment ENABLE ROW LEVEL SECURITY;
CREATE POLICY partner_assignment_internal ON partner_assignment FOR ALL TO ocs_app
  USING (app.is_internal()) WITH CHECK (app.is_internal());
CREATE POLICY partner_assignment_client_read ON partner_assignment FOR SELECT TO ocs_app
  USING (app.actor_kind() = 'client' AND client_id = ANY (app.client_ids()));
-- No DELETE on either table: archive with archived_at (SOP-DEL-02 "never delete").
GRANT SELECT, INSERT, UPDATE ON partner_assignment TO ocs_app;
